import itertools

def find_all_normalized_pairs(n):
    n_sq = n*n
    count = 0
    for X in itertools.combinations(range(n_sq), n):
        if X[0] != 0: continue
        # To optimize, we only check Y if X is "promising".
        # For Y to exist, the differences between elements of X must be 
        # consistent with the set {1, ..., n^2}.
        # Let's just try all Y for now.
        for Y in itertools.combinations(range(1, n_sq + 1), n):
            s = set()
            for xi in X:
                for yj in Y:
                    s.add(xi + yj)
            if s == set(range(1, n_sq + 1)):
                count += 1
    return count

print(f"n=5: {find_all_normalized_pairs(5)}")

import itertools

def find_all_normalized_pairs(n):
    n_sq = n*n
    results = []
    for X in itertools.combinations(range(n_sq), n):
        if X[0] != 0: continue
        for Y in itertools.combinations(range(1, n_sq + 1), n):
            s = set()
            for xi in X:
                for yj in Y:
                    s.add(xi + yj)
            if s == set(range(1, n_sq + 1)):
                results.append((X, Y))
    return results

