import itertools

def find_all_normalized_pairs(n):
    n_sq = n*n
    count = 0
    for X in itertools.combinations(range(n_sq), n):
        if X[0] != 0: continue
        max_x = X[-1]
        if n_sq - max_x < n:
            continue
        for Y in itertools.combinations(range(1, n_sq - max_x + 1), n):
            s = set()
            for xi in X:
                for yj in Y:
                    s.add(xi + yj)
            if len(s) == n_sq:
                count += 1
    return count

print(f"n=6: {find_all_normalized_pairs(6)}")

import itertools

def is_good(n):
    count = 0
    all_nums = list(range(1, n*n + 1))
    for p in itertools.permutations(all_nums):
        a = [p[i*n:(i+1)*n] for i in range(n)]
        is_good_matrix = True
        for i in range(n):
            for j in range(n):
                if a[i][j] != a[i][0] + a[0][j] - a[0][0]:
                    is_good_matrix = False
                    break
            if not is_good_matrix:
                break
        if is_good_matrix:
            count += 1
    return count

print(f"n=3: {is_good(3)}")
